from fractions import Fraction as F
rows=[('A',15,1,0,0,1),('A',9,0,1,1,1),('B',6,1,0,0,0),('B',5,0,1,0,0),('C',9,1,1,1,1),('C',5,0,1,1,0),('D',14,0,0,0,0),('D',9,1,1,1,0)]
tests='TUVW'
cost=dict(zip(tests,map(F,['0.8','1.2','0.7','1.4'])))
loss={'A':[0,24,11,6],'B':[19,0,19,8],'C':[9,10,0,16],'D':[21,24,20,0]}
def stop(rs):
 w=sum(r[1] for r in rs)
 return min((F(sum(r[1]*loss[a]['ABCD'.index(r[0])] for r in rs),w),a) for a in loss)
def value(rs, available, n):
 best=stop(rs)
 if n:
  for t in available:
   v=cost[t]
   for b in (0,1):
    sub=[r for r in rs if r[2+tests.index(t)]==b]
    if sub: v+=F(sum(r[1] for r in sub),sum(r[1] for r in rs))*value(sub,[x for x in available if x!=t],n-1)[0]
   best=min(best,(v,t))
 return best
first_losses={'STOP':float(stop(rows)[0])}
for t in tests:
 v=cost[t]
 for b in (0,1):
  sub=[r for r in rows if r[2+tests.index(t)]==b]
  if sub:v+=F(sum(r[1] for r in sub),sum(r[1] for r in rows))*value(sub,[x for x in tests if x!=t],1)[0]
 first_losses[t]=float(v)
first=value(rows,list(tests),2)[1]
nxt={str(b):value([r for r in rows if r[2+tests.index(first)]==b],[x for x in tests if x!=first],1)[1] for b in (0,1)} if first in tests else {}
import json
print(json.dumps({'first':first,'first_losses':first_losses,'next':nxt}))
print('branch details',[(b,value([r for r in rows if r[2+tests.index(first)]==b],[x for x in tests if x!=first],1)) for b in (0,1)])

