from fractions import Fraction as F
import json
# V=0 selects these rows; a repeat of the same stored reading adds no evidence.
rows=[('A',15,1,0,1),('B',6,1,0,0),('B',5,0,1,0),('D',14,0,0,0)]
modes='ABCD'; tests='TUW'
loss={'A':[0,24,11,6],'B':[19,0,19,8],'C':[9,10,0,16],'D':[21,24,20,0]}
cost={'T':F('0.8'),'U':F('1.2'),'W':F('7.4')}
def repair_values(rs):
 total=sum(r[1] for r in rs)
 return {a:F(sum(r[1]*loss[a][modes.index(r[0])] for r in rs),total) for a in modes}
remaining=repair_values(rows)
policies={}
for t in tests:
 v=cost[t]; policy={}
 for b in (0,1):
  sub=[r for r in rows if r[2+tests.index(t)]==b]
  if not sub: policy[str(b)]='IMPOSSIBLE'; continue
  rv=repair_values(sub)
  a=min(rv,key=rv.get); policy[str(b)]=a
  v+=F(sum(r[1] for r in sub),40)*rv[a]
 remaining[t]=v; policies[t]=policy
act=min(remaining,key=remaining.get)
result={'posterior':{m:float(F(sum(r[1] for r in rows if r[0]==m),40)) for m in modes},'remaining_losses':{a:float(v) for a,v in remaining.items()},'action':act,'repair_after':policies.get(act,{})}
# Check weighted numerators independently for each test's optimal terminal repairs.
assert remaining['T']==F(101,20) # .8 + (14*6 + 15*0 + 6*24 + 5*0)/40
assert remaining['U']==F(153,20) # 1.2 + (14*6 + 6*24 + 15*0 + 5*0)/40
assert remaining['W']==F(41,5) # 7.4 + (6*0 + 5*0 + 14*8)/40
print(json.dumps(result))

